-- Retained numerical roll candidates, not calendar or historical-receipt acceptance.
CREATE TABLE IF NOT EXISTS population_top3000_202608_202609_v1.ctx14_roll_evidence_v6(
 root text PRIMARY KEY CHECK(root IN('ES','MES','NQ','MNQ','RTY','M2K','YM','MYM')),
 evidence jsonb NOT NULL,evidence_sha256 text NOT NULL,
 first_attempt_id uuid NOT NULL REFERENCES population_top3000_202608_202609_v1.pipeline_attempt(attempt_id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(evidence_sha256=encode(sha256(convert_to(evidence::text,'UTF8')),'hex')));
ALTER TABLE population_top3000_202608_202609_v1.ctx14_roll_evidence_v6 ENABLE ROW LEVEL SECURITY;
