CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(p_root text)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path TO pg_catalog AS $f$
DECLARE q record;d record;x record;pages integer;bad integer;manifests jsonb:='[]';bars jsonb:='[]';a jsonb;b jsonb;pair record;result jsonb;
BEGIN
 IF p_root IS NULL OR p_root NOT IN('ES','MES','NQ','MNQ','RTY','M2K','YM','MYM') THEN RAISE EXCEPTION 'CTX14_ROLL_ROOT_REQUIRED';END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ctx14_http_request_v3 WHERE manifest->>'root'=p_root AND manifest->>'resolution'='1min')<>2 THEN RAISE EXCEPTION 'CTX14_ROLL_EXACT_TWO_REQUESTS_REQUIRED';END IF;
 FOR q IN SELECT * FROM population_top3000_202608_202609_v1.ctx14_http_request_v3 WHERE manifest->>'root'=p_root AND manifest->>'resolution'='1min' ORDER BY request_key LOOP
  IF q.manifest->>'contract_symbol' NOT IN(p_root||'U6',p_root||'Z6') OR q.manifest_sha256<>encode(sha256(convert_to(q.manifest::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'CTX14_ROLL_MANIFEST_CHANGED';END IF;
  SELECT count(*) INTO pages FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 WHERE partition_key=q.request_key;
  IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 pp JOIN population_top3000_202608_202609_v1.source_document ss USING(source_id) WHERE pp.partition_key=q.request_key) IS DISTINCT FROM pages THEN RAISE EXCEPTION 'CTX14_ROLL_ORIGINAL_MISSING';END IF;
  IF pages NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'CTX14_ROLL_PAGES_BOUND';END IF;
  SELECT count(*) INTO bad FROM(SELECT p.*,row_number() OVER(ORDER BY page_number) rn,lag(next_url) OVER(ORDER BY page_number) prior_next FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 p WHERE partition_key=q.request_key) z
  WHERE page_number<>rn OR (page_number=1 AND request_url IS DISTINCT FROM q.manifest->>'first_url') OR (page_number>1 AND request_url IS DISTINCT FROM prior_next) OR (page_number<pages AND next_url IS NULL) OR (page_number=pages AND next_url IS NOT NULL);
  IF bad<>0 THEN RAISE EXCEPTION 'CTX14_ROLL_CHAIN_NOT_COMPLETE';END IF;
  FOR d IN SELECT p.*,s.content_text,s.content_bytes,s.source_provider,s.source_published_at,s.historical_received_at FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 p JOIN population_top3000_202608_202609_v1.source_document s USING(source_id) WHERE p.partition_key=q.request_key ORDER BY page_number LOOP
   IF d.source_sha256 IS DISTINCT FROM encode(sha256(convert_to(d.content_text,'UTF8')),'hex') OR d.content_bytes<>octet_length(d.content_text) OR d.content_bytes>8388608 OR d.source_provider IS DISTINCT FROM 'Massive' OR d.content_text::jsonb->>'status' IS DISTINCT FROM 'OK' OR d.result_count IS DISTINCT FROM jsonb_array_length(d.content_text::jsonb->'results') OR d.next_url IS DISTINCT FROM d.content_text::jsonb->>'next_url' THEN RAISE EXCEPTION 'CTX14_ROLL_ORIGINAL_CHANGED';END IF;
   manifests:=manifests||jsonb_build_array(jsonb_build_object('source_id',d.source_id,'source_sha256',d.source_sha256,'wire_sha256',d.wire_sha256,'request_key',q.request_key,'request_sha256',q.manifest_sha256,'page_number',d.page_number,'records',d.result_count));
   FOR x IN SELECT value,ordinality FROM jsonb_array_elements(d.content_text::jsonb->'results') WITH ORDINALITY WHERE value->>'session_end_date'='2026-09-11' LOOP
    a:=population_top3000_202608_202609_v1.ctx14_http_parse_record_v3(x.value,q.manifest);
    IF (a#>>'{parsed,window_start_ns}')::bigint<1789077600000000000 OR (a#>>'{parsed,window_start_ns}')::bigint+60000000000>1789160400000000000 OR mod((a#>>'{parsed,window_start_ns}')::bigint,60000000000)<>0 THEN RAISE EXCEPTION 'CTX14_ROLL_SESSION_TAG_TIME_CONFLICT';END IF;
    bars:=bars||jsonb_build_array(jsonb_build_object('symbol',x.value->>'ticker','ns',x.value->'window_start','close',x.value->'close','source_id',d.source_id,'source_sha256',d.source_sha256,'source_ordinal',x.ordinality,'raw_record_sha256',encode(sha256(convert_to(x.value::text,'UTF8')),'hex')));
   END LOOP;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(bars) z GROUP BY z->>'symbol',z->>'ns' HAVING count(*)<>1) THEN RAISE EXCEPTION 'CTX14_ROLL_DUPLICATE_BAR';END IF;
 SELECT old.value old_bar,new.value new_bar INTO pair FROM jsonb_array_elements(bars) old(value) JOIN jsonb_array_elements(bars) new(value) ON old.value->>'ns'=new.value->>'ns' WHERE old.value->>'symbol'=p_root||'U6' AND new.value->>'symbol'=p_root||'Z6' ORDER BY (old.value->>'ns')::bigint DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'CTX14_ROLL_SYNCHRONOUS_PAIR_MISSING';END IF;
 result:=jsonb_build_object('kind','CTX14_RETAINED_SYNCHRONOUS_ROLL_CANDIDATE_V6','root',p_root,'method','cme_equity_calendar_monday_roll_v1','target_roll_session','2026-09-14','prior_provider_session','2026-09-11','old',pair.old_bar,'new',pair.new_bar,'gap_new_minus_old',(pair.new_bar->>'close')::numeric-(pair.old_bar->>'close')::numeric,'source_manifest',manifests,'candidate_selection','LATEST_COMMON_OBSERVED_MINUTE_IN_PROVIDER_TAGGED_PRIOR_SESSION','source_representation','RETAINED_HTTP_CANONICAL_BODY_WITH_WIRE_HASH','numerical_candidate_only',true,'calendar_mapping_verified',false,'contract_lifecycle_verified',false,'source_coverage_certified',false,'historical_receipt_qualified',false,'family_accepted',false,'native_contract_prices_preserved',true,'future_dependent_retrospective_adjustment_applied',false);
 RETURN result;
END;$f$;
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.ctx14_roll_process_v6(p_attempt uuid,p_token text)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;e jsonb;h text;n integer:=0;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 IF t.family_id IS DISTINCT FROM 'CTX14' OR t.payload->>'kind' IS DISTINCT FROM 'CTX14_ROLL_EVIDENCE_V6' OR t.partition_key IS DISTINCT FROM 'ctx14-roll-v6:'||(t.payload->>'root') OR t.input_versions->>'scope_sha256' IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR t.input_versions->>'clearing_id' IS DISTINCT FROM '7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7' OR t.input_versions->>'clearing_input_sha256' IS DISTINCT FROM '43d6e1eab9d3348557fee9c9aaa03c16baf4642586e985476527742ab3e216b0' THEN RAISE EXCEPTION 'CTX14_ROLL_TASK_SCOPE';END IF;
 IF t.input_versions->>'candidate_function_sha256' IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(text)'::regprocedure),'UTF8')),'hex') OR t.input_versions->>'parse_function_sha256' IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_http_parse_record_v3(jsonb,jsonb)'::regprocedure),'UTF8')),'hex') THEN RAISE EXCEPTION 'CTX14_ROLL_CODE_CHANGED';END IF;
 IF t.stage NOT IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE') THEN RAISE EXCEPTION 'CTX14_ROLL_STAGE';END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','CTX14_ROLL_INDEPENDENT_CALENDAR_LIFECYCLE_RECEIPT_VERIFICATION_REQUIRED','resumption_condition',jsonb_build_object('root',t.payload->>'root','clearing_id',t.input_versions->>'clearing_id','required','Independent exact source/price/gap verification; calendar and lifecycle reconciliation; historical receipt remains unavailable unless separately evidenced','family_accepted',false));END IF;
 PERFORM population_top3000_202608_202609_v1.d02_daily_resource_guard_v2();
 e:=population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(t.payload->>'root');h:=encode(sha256(convert_to(e::text,'UTF8')),'hex');
 IF h IS DISTINCT FROM t.input_versions->>'evidence_sha256' THEN RAISE EXCEPTION 'CTX14_ROLL_INPUT_CHANGED';END IF;
 IF t.stage='ACQUIRE' THEN INSERT INTO population_top3000_202608_202609_v1.ctx14_roll_evidence_v6(root,evidence,evidence_sha256,first_attempt_id) VALUES(t.payload->>'root',e,h,p_attempt) ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ctx14_roll_evidence_v6 WHERE root=t.payload->>'root' AND evidence=e AND evidence_sha256=h) THEN RAISE EXCEPTION 'CTX14_ROLL_IMMUTABLE_CONFLICT';END IF;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','ctx14-roll-v6:'||t.stage||':'||(t.payload->>'root')||':'||h,'output_sha256',h,'new_committed_units',n,'immutable_output_ids',jsonb_build_array('ctx14-roll-v6:'||(t.payload->>'root')),'input_versions',t.input_versions,'numerical_candidate_only',true,'family_accepted',false));
END;$f$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(text),population_top3000_202608_202609_v1.ctx14_roll_process_v6(uuid,text) FROM PUBLIC,anon,authenticated;

