-- Run after reviewed code exists; all fixture task/adapter/evidence writes roll back.
BEGIN;
SET LOCAL lock_timeout='3s'; SET LOCAL statement_timeout='120s';
CREATE TEMP TABLE roll_test_result(result jsonb) ON COMMIT DROP;
DO $test$
DECLARE ctl jsonb;root text;st text;fn regprocedure;h text;v jsonb;e jsonb;r jsonb;r2 jsonb;tid uuid;a uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;tok text:='roll-synthetic-proof-v6';proof jsonb:='[]';fence_ok boolean:=false;stop_ok boolean:=false;hash_ok boolean:=false;replay_ok boolean:=false;badtoken_ok boolean:=false;source_ok boolean:=false;chain_ok boolean:=false;sourceid text;archive text;lastpage integer;
BEGIN
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX14' AND status='LEASED') THEN RAISE EXCEPTION 'CTX14_ROLL_ACTIVE_ATTEMPT';END IF;
 FOREACH root IN ARRAY ARRAY['ES','MES','NQ','MNQ','RTY','M2K','YM','MYM'] LOOP
  e:=population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(root);
  v:=jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','clearing_id','7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7','clearing_input_sha256','43d6e1eab9d3348557fee9c9aaa03c16baf4642586e985476527742ab3e216b0','evidence_sha256',encode(sha256(convert_to(e::text,'UTF8')),'hex'),'candidate_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(text)'::regprocedure),'UTF8')),'hex'),'parse_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_http_parse_record_v3(jsonb,jsonb)'::regprocedure),'UTF8')),'hex'));
  FOREACH st IN ARRAY ARRAY['ACQUIRE','NORMALIZE','DERIVE','VALIDATE'] LOOP
   fn:=('population_top3000_202608_202609_v1.ctx14_roll_'||lower(st)||'_v6(uuid,text)')::regprocedure;
   h:=encode(sha256(convert_to(pg_get_functiondef(fn),'UTF8')),'hex');
   UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid=fn,function_sha256=h,enabled=true WHERE family_id='CTX14' AND stage=st;
   tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('CTX14',st,'ctx14-roll-v6:'||root,jsonb_build_object('kind','CTX14_ROLL_EVIDENCE_V6','root',root),v,NULL);
   SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid FOR UPDATE;
   IF t.status='LEASED' THEN RAISE EXCEPTION 'CTX14_ROLL_EXISTING_ATTEMPT';END IF;
   a:=gen_random_uuid();
   UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=a,lease_until=clock_timestamp()+interval '5minutes',owner_fence=3,stop_generation=1,executions=executions+1 WHERE task_id=tid;
   INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) VALUES(a,tid,t.executions+1,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,h);
   IF NOT fence_ok THEN
    sourceid:=e#>>'{source_manifest,0,source_id}';
    BEGIN UPDATE population_top3000_202608_202609_v1.source_document SET content_text=content_text||' ' WHERE source_id=sourceid;PERFORM population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(root);RAISE EXCEPTION 'BAD_SOURCE_ACCEPTED';EXCEPTION WHEN check_violation THEN source_ok:=true;WHEN raise_exception THEN IF SQLERRM='CTX14_ROLL_ORIGINAL_CHANGED' THEN source_ok:=true;ELSE RAISE;END IF;END;
    SELECT archive_key INTO archive FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 WHERE source_id=sourceid;
    SELECT max(page_number) INTO lastpage FROM population_top3000_202608_202609_v1.ctx14_http_page_v3 WHERE archive_key=archive;
    BEGIN UPDATE population_top3000_202608_202609_v1.ctx14_http_page_v3 SET next_url='https://api.massive.com/test-pending' WHERE archive_key=archive AND page_number=lastpage;PERFORM population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(root);RAISE EXCEPTION 'NONTERMINAL_SOURCE_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='CTX14_ROLL_CHAIN_NOT_COMPLETE' THEN chain_ok:=true;ELSE RAISE;END IF;END;
    BEGIN PERFORM population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,'wrong');RAISE EXCEPTION 'BAD_TOKEN_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='ATTEMPT_AUTH_FAILED' THEN badtoken_ok:=true;ELSE RAISE;END IF;END;
    BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET owner_fence=2 WHERE attempt_id=a;PERFORM population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,tok);RAISE EXCEPTION 'BAD_FENCE_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='STALE_OWNER_OR_STOP' THEN fence_ok:=true;ELSE RAISE;END IF;END;
    BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;PERFORM population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,tok);RAISE EXCEPTION 'STOP_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='MISSION_HELD_OR_ADMISSION_EXPIRED' THEN stop_ok:=true;ELSE RAISE;END IF;END;
    BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=jsonb_set(input_versions,'{evidence_sha256}','"bad"') WHERE task_id=tid;PERFORM population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,tok);RAISE EXCEPTION 'BAD_HASH_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='CTX14_ROLL_INPUT_CHANGED' THEN hash_ok:=true;ELSE RAISE;END IF;END;
   END IF;
   r:=population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,tok);
   IF st='VALIDATE' THEN
    IF r->>'state' IS DISTINCT FROM 'BLOCKED' THEN RAISE EXCEPTION 'FALSE_ACCEPTANCE';END IF;
   ELSE
    IF r->>'state' IS DISTINCT FROM 'COMPLETE' OR r#>>'{commit_receipt,output_sha256}' IS DISTINCT FROM v->>'evidence_sha256' THEN RAISE EXCEPTION 'OUTPUT_MISMATCH';END IF;
    PERFORM population_top3000_202608_202609_v1.pipeline_record_commit_v1(a,tok,r->'commit_receipt');
    IF st='ACQUIRE' THEN
     r2:=population_top3000_202608_202609_v1.ctx14_roll_process_v6(a,tok);
     IF r2#>>'{commit_receipt,new_committed_units}' IS DISTINCT FROM '0' THEN RAISE EXCEPTION 'REPLAY_DUPLICATE';END IF;replay_ok:=true;
    END IF;
   END IF;
   proof:=proof||jsonb_build_array(jsonb_build_object('root',root,'stage',st,'state',r->>'state','output_sha256',v->>'evidence_sha256'));
  END LOOP;
 END LOOP;
 IF NOT(fence_ok AND stop_ok AND hash_ok AND replay_ok AND badtoken_ok AND source_ok AND chain_ok) OR jsonb_array_length(proof)<>32 THEN RAISE EXCEPTION 'INCOMPLETE_PROOF';END IF;
 INSERT INTO roll_test_result VALUES(jsonb_build_object('result','PASS_ACTUAL_CTX14_ROLL_ROLLBACK','roots',8,'stage_proofs',proof,'stale_fence_rejected',fence_ok,'user_stop_rejected',stop_ok,'bad_hash_rejected',hash_ok,'idempotent_replay',replay_ok,'bad_token_rejected',badtoken_ok,'raw_source_corruption_rejected',source_ok,'nonterminal_chain_rejected',chain_ok,'provider_calls',0,'family_accepted',false));
END;$test$;
SELECT result FROM roll_test_result;
ROLLBACK;

