 BEGIN UPDATE population_top3000_202608_202609_v1.ctx14_http_page_v3 SET next_url='https://api.massive.com/test-pending' WHERE archive_key=archive AND page_number=lastpage;PERFORM population_top3000_202608_202609_v1.ctx14_roll_candidate_v6('ES');RAISE EXCEPTION 'NONTERMINAL_SOURCE_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='CTX14_ROLL_CHAIN_NOT_COMPLETE' THEN chain_ok:=true;ELSE RAISE;END IF;END;
