 INSERT INTO roll_source_negative VALUES(jsonb_build_object('result','PASS_CTX14_ROLL_SOURCE_NEGATIVE','raw_source_corruption_rejected',source_ok,'nonterminal_chain_rejected',chain_ok,'provider_calls',0));
