causal_roll_register_v6.sql:
-- Root wraps this registration in same transaction as reviewed code installation.
-- Required temp table ctx14_roll_registration_meta(review jsonb,runtime_receipt jsonb,git_commit text).
DO $register$
DECLARE ctl jsonb;m record;q record;root text;e jsonb;v jsonb;tid uuid;ids jsonb:='[]';pre jsonb;post jsonb;rev bigint;testid bigint;ev bigint;prior_auth jsonb;manifest jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton AND deadline=TIMESTAMPTZ '2026-10-25T22:36:17.687194Z') THEN RAISE EXCEPTION 'CTX14_ROLL_DEADLINE_CHANGED';END IF;
 PERFORM 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7' AND status='CLAIMED' AND owner_id=ctl->>'owner_id' AND owner_fence=3 AND stop_generation=1 AND claim_expires_at>clock_timestamp() AND input_sha256='43d6e1eab9d3348557fee9c9aaa03c16baf4642586e985476527742ab3e216b0' AND assignment_event_id=18255 FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=19938 AND event='ENGINEERING_CLEARING_CLAIMED_V6' AND details->>'assignment_event_id'='18255') THEN RAISE EXCEPTION 'CTX14_ROLL_EXACT_LIVE_CLAIM_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX14' AND status='LEASED') THEN RAISE EXCEPTION 'CTX14_ROLL_ACTIVE_ATTEMPT';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX14_ROLL_INTEGRATED_V6' AND details->>'claim_event_id'='19938') THEN RAISE EXCEPTION 'CTX14_ROLL_ALREADY_INTEGRATED';END IF;
 SELECT * INTO STRICT m FROM ctx14_roll_registration_meta;
 IF m.review->>'approved' IS DISTINCT FROM 'true' OR m.review->>'reviewer' IS DISTINCT FROM 'ctx14_review' OR m.runtime_receipt->>'result' IS DISTINCT FROM 'PASS_ACTUAL_CTX14_ROLL_ROLLBACK' OR m.runtime_receipt->>'roots' IS DISTINCT FROM '8' OR m.runtime_receipt->>'stale_fence_rejected' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'user_stop_rejected' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'bad_hash_rejected' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'idempotent_replay' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'bad_token_rejected' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'raw_source_corruption_rejected' IS DISTINCT FROM 'true' OR m.runtime_receipt->>'nonterminal_chain_rejected' IS DISTINCT FROM 'true' OR m.git_commit!~'^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'CTX14_ROLL_REVIEW_RUNTIME_REQUIRED';END IF;
 FOR q IN SELECT * FROM (VALUES('ACQUIRE','92033999d8ad481341daf4cc3cdbe22779979d2c1429325f5fbff18d6a38bbfe'),('NORMALIZE','ce32e609a96fdf36ade2dbf1f5b710d205d1ef4c990e6c789690c7a052fc73f0'),('DERIVE','39f209c8c8bd29b50fd213d8f64ab4b651b3a65f1521338712c0d747c74c46eb'),('VALIDATE','46f81a2cacc5b1e042fbca4be0d395a71e9128817c7aca5c00ab0d8cb26fdcf9')) x(stage,hash) LOOP
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_adapter a WHERE a.family_id='CTX14' AND a.stage=q.stage AND a.function_sha256=q.hash AND a.function_sha256=encode(sha256(convert_to(pg_get_functiondef(a.function_oid),'UTF8')),'hex')) THEN RAISE EXCEPTION 'CTX14_ROLL_PREIMAGE_CHANGED %',q.stage;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 c CROSS JOIN LATERAL jsonb_array_elements(c.input_manifest) pin LEFT JOIN population_top3000_202608_202609_v1.pipeline_task t ON t.task_id=(pin->>'task_id')::uuid WHERE c.clearing_id='7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7' AND (t.status IS DISTINCT FROM 'BLOCKED' OR t.blocker_code IS DISTINCT FROM c.blocker_code OR t.checkpoint IS DISTINCT FROM pin->'checkpoint' OR t.executions::text IS DISTINCT FROM pin->>'executions' OR t.cumulative_failures::text IS DISTINCT FROM pin->>'cumulative_failures' OR t.input_versions IS DISTINCT FROM pin->'input_versions' OR encode(sha256(convert_to(t.payload::text,'UTF8')),'hex') IS DISTINCT FROM pin->>'payload_sha256')) THEN RAISE EXCEPTION 'CTX14_ROLL_ORIGINAL_REQUIREMENT_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX14_ROLL_INDEPENDENT_REVIEW_V6',m.review||ctl||jsonb_build_object('clearing_id','7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7','claim_event_id',19938,'git_commit',m.git_commit)) RETURNING event_id INTO rev;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX14_ROLL_ACTUAL_TEST_V6',ctl||jsonb_build_object('runtime_receipt',m.runtime_receipt,'claim_event_id',19938,'git_commit',m.git_commit)) RETURNING event_id INTO testid;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY stage) INTO pre FROM population_top3000_202608_202609_v1.pipeline_adapter a WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid=('population_top3000_202608_202609_v1.ctx14_roll_'||lower(stage)||'_v6(uuid,text)')::regprocedure,function_sha256=encode(sha256(convert_to(pg_get_functiondef(('population_top3000_202608_202609_v1.ctx14_roll_'||lower(stage)||'_v6(uuid,text)')::regprocedure),'UTF8')),'hex'),reviewed_test_evidence=coalesce(reviewed_test_evidence,'{}')||jsonb_build_object('roll_v6',jsonb_build_object('review_event_id',rev,'test_event_id',testid,'git_commit',m.git_commit)),producer_revision='ctx14-roll-v6-'||left(m.git_commit,12),enabled=true WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 FOREACH root IN ARRAY ARRAY['ES','MES','NQ','MNQ','RTY','M2K','YM','MYM'] LOOP
  e:=population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(root);
  v:=jsonb_build_object('scope_sha256',ctl->>'scope_sha256','clearing_id','7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7','clearing_input_sha256','43d6e1eab9d3348557fee9c9aaa03c16baf4642586e985476527742ab3e216b0','evidence_sha256',encode(sha256(convert_to(e::text,'UTF8')),'hex'),'candidate_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(text)'::regprocedure),'UTF8')),'hex'),'parse_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_http_parse_record_v3(jsonb,jsonb)'::regprocedure),'UTF8')),'hex'));
  tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('CTX14','ACQUIRE','ctx14-roll-v6:'||root,jsonb_build_object('kind','CTX14_ROLL_EVIDENCE_V6','root',root),v,NULL);
  ids:=ids||jsonb_build_array(jsonb_build_object('task_id',tid,'root',root,'evidence_sha256',v->>'evidence_sha256'));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY stage) INTO post FROM population_top3000_202608_202609_v1.pipeline_adapter a WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX14_ROLL_INTEGRATED_V6',ctl||jsonb_build_object('claim_event_id',19938,'assignment_event_id',18255,'clearing_id','7f2b584c2ca4d4b667087b79aa4a11f8145551e2d9991f429484fc0a2d9501b7','independent_review_event_id',rev,'actual_test_event_id',testid,'git_commit',m.git_commit,'new_tasks',ids,'prior_adapters',pre,'installed_adapters',post,'original_requirements_preserved',true,'family_accepted',false,'useful_output_observed',false)) RETURNING event_id INTO ev;
 -- Preserve existing recovery authority and counters; repin only reviewed additive adapters.
 SELECT details INTO prior_auth FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RECOVERY_DELEGATION_QUALIFIED_V1' ORDER BY event_id DESC LIMIT 1;
 IF prior_auth IS NULL OR prior_auth->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR prior_auth->>'owner_fence' IS DISTINCT FROM '3' OR prior_auth->>'stop_generation' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'CTX14_ROLL_RECOVERY_AUTHORITY_REQUIRED';END IF;
 manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RECOVERY_DELEGATION_QUALIFIED_V1',prior_auth||jsonb_build_object('code_manifest',manifest,'engineering_event_id',ev,'qualification_reason','Reviewed additive CTX14 roll numerical candidate adapters; existing authority expiry, restarts, counters and clocks unchanged','independent_review_event_id',rev,'actual_runtime_event_id',testid));
 PERFORM population_top3000_202608_202609_v1.pipeline_wake_v1(ctl->>'owner_id',3,'CTX14 retained synchronous roll candidates: execute8 pinned tasks and verification successors');
END;$register$;
